from typing import List

class Solution:
    def numberOfPermutations(self, n: int, requirements: List[List[int]]) -> int:
        MOD = 10**9 + 7
        M = 400
        req = {}
        for e, c in requirements:
            req[e] = c

        dp = [0] * (M + 1)
        dp[0] = 1  # empty prefix, 0 inversions

        for i in range(n):
            # prefix sums of dp
            S = [0] * (M + 1)
            run = 0
            for j in range(M + 1):
                run = (run + dp[j]) % MOD
                S[j] = run
            new = [0] * (M + 1)
            for j in range(M + 1):
                lo = j - i - 1
                val = S[j]
                if lo >= 0:
                    val -= S[lo]
                new[j] = val % MOD
            dp = new
            if i in req:
                c = req[i]
                keep = dp[c] if c <= M else 0
                dp = [0] * (M + 1)
                dp[c] = keep if c <= M else 0

        return sum(dp) % MOD
