class Solution:
    def numberOfPermutations(self, n: int, requirements: List[List[int]]) -> int:
        MOD = 10**9 + 7
        K = 401  # inversion counts 0..400 are sufficient
        req = {}
        for end, cnt in requirements:
            req[end] = cnt

        dp = [0] * K
        dp[0] = 1  # empty prefix
        for m in range(1, n + 1):
            # prefix sums of dp
            P = [0] * (K + 1)
            for i in range(K):
                P[i + 1] = (P[i] + dp[i]) % MOD
            w = m - 1  # new element can add 0..m-1 inversions
            new = [0] * K
            for c in range(K):
                lo = c - w
                if lo < 0:
                    lo = 0
                new[c] = (P[c + 1] - P[lo]) % MOD
            idx = m - 1
            if idx in req:
                target = req[idx]
                keep = new[target] if target < K else 0
                new = [0] * K
                if target < K:
                    new[target] = keep
            dp = new

        return sum(dp) % MOD
