class Solution:
    def numberOfPermutations(self, n: int, requirements: List[List[int]]) -> int:
        MOD = 10**9 + 7
        K = 400
        req = [-1] * n
        for e, c in requirements:
            req[e] = c

        dp = [0] * (K + 1)
        dp[0] = 1  # empty prefix, 0 inversions

        for i in range(n):
            # prefix sums of dp
            P = [0] * (K + 1)
            s = 0
            for j in range(K + 1):
                s = (s + dp[j]) % MOD
                P[j] = s
            new = [0] * (K + 1)
            for j in range(K + 1):
                # sum dp[j-r] for r in 0..i  => P[j] - P[j-i-1]
                val = P[j]
                if j - i - 1 >= 0:
                    val -= P[j - i - 1]
                new[j] = val % MOD
            dp = new
            if req[i] != -1:
                c = req[i]
                for j in range(K + 1):
                    if j != c:
                        dp[j] = 0

        return sum(dp) % MOD
