class Solution:
    def numberOfPermutations(self, n: int, requirements: List[List[int]]) -> int:
        MOD = 10**9 + 7
        K = 400
        req = {}
        for e, c in requirements:
            req[e] = c

        def apply_req(dp, idx):
            if idx in req:
                c = req[idx]
                new = [0] * (K + 1)
                if c <= K:
                    new[c] = dp[c]
                return new
            return dp

        dp = [0] * (K + 1)
        dp[0] = 1
        dp = apply_req(dp, 0)

        for L in range(1, n):
            # new element adds j in [0, L]
            S = [0] * (K + 1)
            run = 0
            for k in range(K + 1):
                run = (run + dp[k]) % MOD
                S[k] = run
            ndp = [0] * (K + 1)
            for k in range(K + 1):
                val = S[k]
                t = k - L - 1
                if t >= 0:
                    val -= S[t]
                ndp[k] = val % MOD
            dp = apply_req(ndp, L)

        return sum(dp) % MOD

